+@page "/catalog"
+@namespace sv_9e93fc10a58f488e9af03860810d5dbc.Components.Pages.Catalog
+@rendermode InteractiveServer
+@inject IProductService ProductService
+
+<PageTitle>Product Catalog</PageTitle>
+
+<h3 class="mb-4">Product Catalog</h3>
+
+<div class="row">
+    @* Left Sidebar — Filters *@
+    <div class="col-md-3">
+        <CatalogFilters Categories="categories"
+                        OnFilterApplied="HandleFilterApplied"
+                        OnFilterCleared="HandleFilterCleared" />
+    </div>
+
+    @* Main Content Area *@
+    <div class="col-md-9">
+        @if (isLoading)
+        {
+            <div class="d-flex justify-content-center py-5">
+                <div class="spinner-border text-primary" role="status">
+                    <span class="visually-hidden">Loading...</span>
+                </div>
+            </div>
+        }
+        else if (errorMessage is not null)
+        {
+            <div class="alert alert-danger" role="alert">
+                <strong>Error:</strong> @errorMessage
+            </div>
+        }
+        else if (result is null || result.Items.Count == 0)
+        {
+            <div class="alert alert-info" role="alert">
+                No products found matching your criteria. Try adjusting your filters.
+            </div>
+        }
+        else
+        {
+            <CatalogToolbar CurrentSort="@currentSort"
+                            Page="currentPage"
+                            PageSize="pageSize"
+                            TotalCount="result.TotalCount"
+                            OnSortChanged="HandleSortChanged" />
+
+            <ProductGrid Products="result.Items"
+                         OnProductSelected="HandleProductSelected"
+                         OnAddToCart="HandleAddToCart" />
+
+            <CatalogPagination CurrentPage="currentPage"
+                               TotalPages="TotalPages"
+                               OnPageChanged="HandlePageChanged" />
+        }
+    </div>
+</div>
+
+@code {
+    [Parameter]
+    public EventCallback<Product> OnProductSelected { get; set; }
+
+    private List<string> categories = [];
+    private PagedResult<Product>? result;
+    private ProductFilter currentFilter = new(null, null, null, false);
+    private string currentSort = "price_asc";
+    private int currentPage = 1;
+    private const int pageSize = 12;
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    private int TotalPages => result is null || result.TotalCount == 0
+        ? 0
+        : (int)Math.Ceiling((double)result.TotalCount / pageSize);
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadDataAsync();
+    }
+
+    private async Task LoadDataAsync()
+    {
+        try
+        {
+            isLoading = true;
+            errorMessage = null;
+
+            var categoriesTask = ProductService.GetCategoriesAsync();
+            var productsTask = ProductService.SearchAsync(currentFilter, currentSort, currentPage, pageSize);
+
+            await Task.WhenAll(categoriesTask, productsTask);
+
+            categories = await categoriesTask;
+            result = await productsTask;
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task SearchAsync()
+    {
+        try
+        {
+            isLoading = true;
+            errorMessage = null;
+            result = await ProductService.SearchAsync(currentFilter, currentSort, currentPage, pageSize);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task HandleFilterApplied(ProductFilter filter)
+    {
+        currentFilter = filter;
+        currentPage = 1;
+        await SearchAsync();
+    }
+
+    private async Task HandleFilterCleared()
+    {
+        currentFilter = new ProductFilter(null, null, null, false);
+        currentPage = 1;
+        await SearchAsync();
+    }
+
+    private async Task HandleSortChanged(string sort)
+    {
+        currentSort = sort;
+        currentPage = 1;
+        await SearchAsync();
+    }
+
+    private async Task HandlePageChanged(int page)
+    {
+        currentPage = page;
+        await SearchAsync();
+    }
+
+    private async Task HandleProductSelected(Product product)
+    {
+        await OnProductSelected.InvokeAsync(product);
+    }
+
+    private Task HandleAddToCart(Product product)
+    {
+        // Placeholder for cart integration
+        return Task.CompletedTask;
+    }
+}
